REVOKE EXECUTE ON FUNCTION public.create_study_profile() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.validate_study_item() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p jsonb:=NEW.payload; ref uuid; BEGIN IF NEW.kind IN ('questions','mock') THEN IF NOT (p ?& ARRAY['total','correct','wrong','blank','date','contest_id']) OR (p->>'total')::integer<=0 OR (p->>'correct')::integer<0 OR (p->>'wrong')::integer<0 OR (p->>'blank')::integer<0 OR (p->>'correct')::integer+(p->>'wrong')::integer+(p->>'blank')::integer<>(p->>'total')::integer THEN RAISE EXCEPTION 'Acertos + erros + brancos devem ser iguais ao total'; END IF; END IF; IF NEW.kind='link' AND (p->>'confirmed')::boolean IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Confirme a equivalência'; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.validate_study_session() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE ids jsonb; BEGIN IF TG_OP='INSERT' AND NEW.state='running' AND array_length(NEW.contest_ids,1)>1 THEN SELECT payload->'topic_ids' INTO ids FROM study_items WHERE kind='link' AND user_id=NEW.user_id AND (payload->>'confirmed')::boolean AND (payload->'topic_ids') ? NEW.topic_id::text AND NOT EXISTS(SELECT 1 FROM unnest(NEW.contest_ids) c WHERE NOT EXISTS(SELECT 1 FROM study_items t JOIN study_items s ON s.id=(t.payload->>'subject_id')::uuid WHERE t.user_id=NEW.user_id AND t.kind='topic' AND (study_items.payload->'topic_ids') ? t.id::text AND s.payload->>'contest_id'=c::text)) LIMIT 1; IF ids IS NULL THEN RAISE EXCEPTION 'Conteúdos compartilhados precisam de equivalência confirmada'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_session_shared BEFORE INSERT ON public.study_sessions FOR EACH ROW EXECUTE FUNCTION public.validate_study_session();